<?php
namespace Modules\StockTransferNew\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Routing\Controller;use Illuminate\Support\Facades\Auth;use Illuminate\Support\Facades\DB;use Modules\StockTransferNew\Entities\StockTransferApprovalMatrix;use Modules\StockTransferNew\Utilities\StockTransferTenant;
class ApprovalMatrixController extends Controller{public function index(){$matrices=StockTransferApprovalMatrix::with('steps')->where('business_id',StockTransferTenant::businessId())->latest()->paginate(25);return view('stocktransfernew::approval_matrix.index',compact('matrices'));}public function store(Request $request){$data=$request->validate(['approval_mode'=>'required|in:sequential,parallel','min_amount'=>'nullable|numeric','max_amount'=>'nullable|numeric','role_name'=>'nullable|array','approver_user_id'=>'nullable|array']);DB::transaction(function()use($data){$matrix=StockTransferApprovalMatrix::create(['business_id'=>StockTransferTenant::businessId(),'approval_mode'=>$data['approval_mode'],'min_amount'=>$data['min_amount']??0,'max_amount'=>$data['max_amount']??null,'created_by'=>Auth::id()]);$roles=$data['role_name']??[];$users=$data['approver_user_id']??[];foreach($roles as $i=>$role){if(blank($role)&&blank($users[$i]??null)){continue;}$matrix->steps()->create(['step_order'=>$i+1,'role_name'=>$role,'approver_user_id'=>$users[$i]??null]);}});return back()->with('status','Approval matrix saved.');}public function destroy(StockTransferApprovalMatrix $approval_matrix){$approval_matrix->delete();return back()->with('status','Approval matrix removed.');}}
